create or replace function public.client_portal_action(p_submission_id uuid,p_action text,p_feedback text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare p public.profiles%rowtype;s public.candidate_submissions%rowtype;ns text;ast text;begin select * into p from public.profiles where id=auth.uid() and role='viewer' and client_id is not null;if not found then raise exception 'Client access required';end if;select * into s from public.candidate_submissions where id=p_submission_id and company_id=p.company_id and client_id=p.client_id;if not found then raise exception 'Submission not found';end if;ns:=case p_action when 'approve' then 'client_approved' when 'reject' then 'client_rejected' when 'request_interview' then 'interview_requested' end;ast:=case p_action when 'approve' then 'client_approved' when 'reject' then 'rejected' when 'request_interview' then 'interview_requested' end;if ns is null then raise exception 'Invalid action';end if;update public.candidate_submissions set status=ns,client_feedback=nullif(left(trim(coalesce(p_feedback,'')),5000),''),reviewed_at=now(),updated_at=now() where id=s.id;if s.application_id is not null then update public.applications set status=ast where id=s.application_id and company_id=p.company_id;end if;return jsonb_build_object('ok',true,'status',ns);end$$;
create or replace function public.tf_interview_application_status() returns trigger language plpgsql security definer set search_path='' as $$begin if new.status='scheduled' then update public.applications set status='interview' where id=(select id from public.applications where company_id=new.company_id and candidate_id=new.candidate_id and job_id=new.job_id order by submitted_at desc limit 1);elsif new.status='completed' then update public.applications set status='interview_completed' where id=(select id from public.applications where company_id=new.company_id and candidate_id=new.candidate_id and job_id=new.job_id order by submitted_at desc limit 1);end if;return new;end$$;revoke all on function public.tf_interview_application_status() from public,anon,authenticated;drop trigger if exists tf_interview_application_status on public.interviews;create trigger tf_interview_application_status after insert or update of status on public.interviews for each row execute function public.tf_interview_application_status();
create or replace function public.tf_placement_application_status() returns trigger language plpgsql security definer set search_path='' as $$begin update public.applications set status='placed' where id=(select id from public.applications where company_id=new.company_id and candidate_id=new.candidate_id and job_id=new.job_id order by submitted_at desc limit 1);return new;end$$;revoke all on function public.tf_placement_application_status() from public,anon,authenticated;drop trigger if exists tf_placement_application_status on public.placements;create trigger tf_placement_application_status after insert on public.placements for each row execute function public.tf_placement_application_status();
